    if (old && old.key === key) return;
    dirty = true;
    if (old?.m.tool_use_id) {
      if (old.m.role === "tool" && results.get(old.m.tool_use_id) === m.index) results.delete(old.m.tool_use_id);
      if (old.m.role === "assistant" && calls.get(old.m.tool_use_id) === m.index) calls.delete(old.m.tool_use_id);
    }
